// This file is generated by AI.

// 预览客户端单例: 管理预览服务器生命周期、站点注册、sync-scene 命令与宿主事件。

import { addStaticSite, sendPreviewCommand, setEmbeddedPreviewLaunchId, startPreviewServer } from '../commands/server';
import { sceneNameFromPath } from '../lib/uri';
import { useAppStore } from '../state/store';
import { createId, createRequestEnvelope, type HostEventType } from './protocol';

class PreviewClient {
  private serverUrl: string | null = null;
  private siteUrl: string | null = null;
  private pendingServer: Promise<string | null> | null = null;

  private buildServeUrl(siteId: string, server: string): string {
    const base = server.endsWith('/') ? server : server + '/';
    return new URL(`game/${siteId}/`, base).href;
  }

  async ensureServer(): Promise<string | null> {
    if (this.serverUrl) return this.serverUrl;
    if (this.pendingServer) return this.pendingServer;

    this.pendingServer = (async () => {
      try {
        const url = await startPreviewServer('127.0.0.1', 8899, (msg) => this.consumeHostEvent(msg));
        this.serverUrl = url;
        return url;
      } catch (e) {
        console.error('预览服务器启动失败', e);
        return null;
      } finally {
        this.pendingServer = null;
      }
    })();

    return this.pendingServer;
  }

  async ensureSite(projectPath: string, enginePath?: string): Promise<string | null> {
    if (this.siteUrl) return this.siteUrl;
    const server = await this.ensureServer();
    if (!server) return null;
    const siteId = await addStaticSite(projectPath, enginePath ?? undefined);
    this.siteUrl = this.buildServeUrl(siteId, server);
    useAppStore.getState().setPreview({ previewServerUrl: server, previewSiteId: siteId });
    return this.siteUrl;
  }

  /** 项目切换/关闭时清空站点缓存。 */
  resetSite(): void {
    this.siteUrl = null;
  }

  async bindEmbeddedLaunchId(id: string | null): Promise<void> {
    await setEmbeddedPreviewLaunchId(id ?? undefined);
  }

  async syncScene(scenePath: string, lineNumber: number): Promise<void> {
    if (!this.siteUrl) return;

    const sceneName = sceneNameFromPath(scenePath);
    const request = createRequestEnvelope('preview.command.sync-scene', createId(), {
      sceneName,
      sentenceId: lineNumber,
    });
    try {
      await sendPreviewCommand(JSON.stringify(request));
    } catch (e) {
      console.error('sync-scene 发送失败', e);
    }
  }

  private consumeHostEvent(raw: string): void {
    let msg: { kind?: string; type?: string; payload?: Record<string, unknown> };
    try {
      msg = JSON.parse(raw) as typeof msg;
    } catch {
      return;
    }
    if (msg.kind !== 'event' || typeof msg.type !== 'string') return;

    const type = msg.type as HostEventType;
    if (type === 'preview.ready.updated') {
      const ready = Boolean(msg.payload?.ready);
      useAppStore.getState().setPreview({ previewReady: ready });
    } else if (type === 'stage.snapshot.updated') {
      const p = msg.payload ?? {};
      useAppStore.getState().setPreview({
        previewStage: {
          sceneName: String(p.sceneName ?? ''),
          sentenceId: Number(p.sentenceId ?? 0),
        },
      });
    }
  }
}

export const previewClient = new PreviewClient();
